def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_count = 0
    rich_alive = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 200:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.85:
                    aggressive_count += 1

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.2))

    slots = supply / float(WATER_REQ)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if slots <= 1.05:
        danger += 3
    elif slots <= 1.35:
        danger += 2
    elif slots <= 1.7:
        danger += 1

    if aggressive_count >= 1:
        danger += 1
    if rich_alive >= 1:
        danger += 1

    if day >= 8:
        danger += 1

    if danger <= 1:
        bid = DAILY_SALARY * 0.22
    elif danger == 2:
        bid = DAILY_SALARY * 0.34
    elif danger == 3:
        bid = DAILY_SALARY * 0.48
    elif danger == 4:
        bid = DAILY_SALARY * 0.62
    elif danger == 5:
        bid = DAILY_SALARY * 0.78
    else:
        bid = DAILY_SALARY * 0.93

    if highest_prev > 0:
        if danger >= 5:
            bid = max(bid, min(DAILY_SALARY * 0.98, highest_prev + 2.0))
        elif danger >= 3:
            bid = max(bid, min(DAILY_SALARY * 0.75, avg_prev + 1.0))
        else:
            bid = min(bid, highest_prev * 0.7)

    if slots >= 1.9 and hp >= 5:
        bid = min(bid, DAILY_SALARY * 0.25)

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.7)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.95))

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / len(prev_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(max_prev * 1.05, DAILY_SALARY * 0.9))

    if supply < 18:
        return min(my_status['budget'], max(avg_prev * 1.1, DAILY_SALARY * 0.7))

    return min(my_status['budget'], max(avg_prev * 0.8, DAILY_SALARY * 0.5))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    alive = {k: v for k, v in opponents_status.items() if v['alive']}

    # Determine highest previous bid among alive opponents
    prev_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace:
            prev_bids.append(trace['bid'])

    if prev_bids:
        max_prev = max(prev_bids)
    else:
        max_prev = 0

    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    # Urgency based on hp and no_water
    if hp <= 2 or no_water > 1:
        # Need water urgently: bid competitive
        bid = min(budget, max(DAILY_SALARY * 0.9, max_prev + 1))
    elif hp <= 4:
        bid = min(budget, max(DAILY_SALARY * 0.6, max_prev + 0.5))
    else:
        # Healthy: can afford to bid low or moderate
        if max_prev >= DAILY_SALARY * 0.8:
            bid = min(budget, DAILY_SALARY * 0.4)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.3, max_prev + 1.0))

    # Ensure bid does not exceed budget
    return min(bid, budget)
